function escapeName(name: string, charsToEscape: Set<number>): string {
    let lastIndex = 0;
    let escapedName = "";

    for (let index = 0; index < name.length; index++) {
        const charCode = name.charCodeAt(index);
        let needsEscape = charsToEscape.has(charCode);

        // Handle leading digit
        if (index === 0 && charCode >= 0x30 && charCode <= 0x39) {
            needsEscape = true;
        }

        // Handle lone hyphen (just `-`)
        if (name.length === 1 && charCode === 0x2d) {
            needsEscape = true;
        }

        // Handle leading hyphen followed by digit
        if (index === 1 && charCode >= 0x30 && charCode <= 0x39 && name.charCodeAt(0) === 0x2d) {
            needsEscape = true;
        }

        // Handle control characters (0x00-0x1f) and DEL (0x7f)
        if ((charCode >= 0x00 && charCode <= 0x1f) || charCode === 0x7f) {
            needsEscape = true;
        }

        if (needsEscape) {
            escapedName += name.slice(lastIndex, index);

            // Special case for null character: use replacement character
            if (charCode === 0x00) {
                escapedName += "\\fffd ";
            }
            // Use hex escape for control characters and digits at start
            else if ((charCode >= 0x00 && charCode <= 0x1f) || charCode === 0x7f ||
                     (index === 0 && charCode >= 0x30 && charCode <= 0x39) ||
                     (index === 1 && charCode >= 0x30 && charCode <= 0x39 && name.charCodeAt(0) === 0x2d) ||
                     (name.length === 1 && charCode === 0x2d)) {
                escapedName += `\\${charCode.toString(16)} `;
            } else {
                // Use backslash escape for other special characters
                escapedName += `\\${name.charAt(index)}`;
            }
            lastIndex = index + 1;
        }
    }

    return escapedName.length > 0 ? escapedName + name.slice(lastIndex) : name;
}

